import * as Sentry from "@sentry/nextjs";
import posthog from "posthog-js";
import { resolveEnvironment } from "@/lib/analytics/posthog";
import { sharedSentryOptions } from "../sentry.shared";

Sentry.init({
  dsn: process.env.NEXT_PUBLIC_SENTRY_DSN,
  enableLogs: true,
  replaysOnErrorSampleRate: 1.0,
  // 0 = buffer mode: the SDK records into memory and uploads only when an
  // error fires. The free plan includes 50 replays/mo — any session sampling
  // exhausts that within days and then error replays stop too. Accepted
  // tradeoff: error classes dropped by ignoreErrors/scrubEvent leave no
  // replay either; if browse-through replay is ever wanted, enable PostHog's
  // (5,000 recordings/mo free) rather than raising this.
  replaysSessionSampleRate: 0,
  // Mask all text and inputs in Session Replay (the /pricing waitlist email
  // field included) — explicit even though these are the defaults.
  integrations: [Sentry.replayIntegration({ maskAllText: true, maskAllInputs: true })],
  ...sharedSentryOptions,
});

// NEXT_PUBLIC_POSTHOG_KEY is inlined at build time; guard for browser + presence
// so missing keys in preview/test builds don't crash the client bundle.
const posthogKey = process.env.NEXT_PUBLIC_POSTHOG_KEY;

if (typeof window !== "undefined" && posthogKey) {
  // Explicit-events-only posture: every implicit capture class is off so the
  // 1M-events/mo free tier goes to events we actually query. Note `defaults`
  // is an SSR/storage behavior bundle, not a cost control — it leaves
  // autocapture on, hence the explicit flags.
  posthog.init(posthogKey, {
    api_host: "/ingest",
    ui_host: "https://eu.posthog.com",
    defaults: "2026-01-30",
    // Sentry owns error tracking; capturing browser exceptions here too would
    // double-bill every error into a second quota.
    capture_exceptions: false,
    autocapture: false,
    // Kept on: PostHog Web Analytics derives bounce rate and session duration
    // from $pageleave — one extra event per pageview buys both metrics.
    capture_pageleave: true,
    capture_dead_clicks: false,
    capture_heatmaps: false,
    capture_performance: false,
    // trackPageView() fires $pageview manually on route changes; the built-in
    // capture would double-count every navigation.
    capture_pageview: false,
    disable_session_recording: true,
    // Anonymous events are ~4x cheaper than identified ones. This is the
    // library default today; pinned so a default flip can't change our billing.
    person_profiles: "identified_only",
    debug: process.env.NODE_ENV === "development",
  });

  // Super property on every event. The website and the iOS app live in
  // separate projects, so this is belt-and-braces — but it means a stray event
  // is always traceable to its origin without inferring from $lib.
  // Super properties on every event. `product` keeps a stray event traceable to
  // its origin even though the website and the app are separate projects;
  // `environment` is what keeps staging out of the north star.
  posthog.register({ product: "marketing_site", environment: resolveEnvironment() });
}

export const onRouterTransitionStart = Sentry.captureRouterTransitionStart;

