import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import posthog from "posthog-js";
import { resolveEnvironment, trackEvent, trackPageView } from "./posthog";

vi.mock("posthog-js", () => ({
  default: {
    init: vi.fn(),
    capture: vi.fn(),
  },
}));

describe("trackPageView", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("sends the full href, not the pathname", () => {
    window.history.pushState({}, "", "/blog/repotting?utm_source=newsletter");

    trackPageView();

    // The query string is what PostHog parses $utm_* and channel type out of;
    // sending a bare pathname is what made channel attribution impossible.
    expect(posthog.capture).toHaveBeenCalledWith("$pageview", {
      $current_url: expect.stringContaining("/blog/repotting?utm_source=newsletter"),
    });
    expect(posthog.capture).toHaveBeenCalledWith("$pageview", {
      $current_url: window.location.href,
    });
  });
});

describe("trackEvent", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("forwards the event name and properties", () => {
    trackEvent("app_store_handoff", {
      page: "/pricing",
      placement: "pricing_card",
      campaign_token: "web-pricing-card",
    });

    expect(posthog.capture).toHaveBeenCalledWith("app_store_handoff", {
      page: "/pricing",
      placement: "pricing_card",
      campaign_token: "web-pricing-card",
    });
  });

  it("returns capture's result so callers can detect a dropped event", () => {
    vi.mocked(posthog.capture).mockReturnValueOnce(undefined);
    expect(trackEvent("waitlist_joined", { source: "web" })).toBeUndefined();
  });
});

describe("resolveEnvironment", () => {
  afterEach(() => {
    vi.unstubAllEnvs();
  });

  it.each(["production", "staging", "development"] as const)(
    "uses the explicit NEXT_PUBLIC_APP_ENV value %s",
    (env) => {
      vi.stubEnv("NEXT_PUBLIC_APP_ENV", env);
      expect(resolveEnvironment()).toBe(env);
    },
  );

  it("falls back to NODE_ENV when the label is unset", () => {
    // APP_ENV (no NEXT_PUBLIC_ prefix) is invisible to the browser, so an
    // unset label is the normal case locally, not an error.
    vi.stubEnv("NEXT_PUBLIC_APP_ENV", "");
    vi.stubEnv("NODE_ENV", "production");
    expect(resolveEnvironment()).toBe("production");

    vi.stubEnv("NODE_ENV", "test");
    expect(resolveEnvironment()).toBe("development");
  });

  it("ignores an unrecognised label rather than trusting it", () => {
    // A typo must not invent a fourth environment that no dashboard filters on.
    vi.stubEnv("NEXT_PUBLIC_APP_ENV", "prod");
    vi.stubEnv("NODE_ENV", "test");
    expect(resolveEnvironment()).toBe("development");
  });
});

