"use client";

import posthog from "posthog-js";

/**
 * Where a download CTA sits on the site. Every instance of DownloadButton
 * declares one, so App Store handoffs can be attributed to the surface that
 * produced them — and so the Apple campaign token (`ct`) carries that surface
 * across the App Store boundary into App Store Connect.
 */
export type Placement =
  | "hero"
  | "header"
  | "header_mobile"
  | "pricing_card"
  | "pricing_free_card"
  | "faq_cta"
  | "cactus_care_cta"
  | "garden_management_cta"
  | "plant_care_cta"
  | "plant_diagnosis_cta";

export type PageType = "blog" | "landing";

export type AppEnvironment = "production" | "staging" | "development";

const ENVIRONMENTS: readonly string[] = ["production", "staging", "development"];

/**
 * Environment label for every event, so staging traffic never silently inflates
 * the north star.
 *
 * Must read NEXT_PUBLIC_APP_ENV, not APP_ENV. Next only inlines the
 * NEXT_PUBLIC_ prefix into the client bundle, so APP_ENV resolves to undefined
 * in the browser however correctly it is set on Railway. That exact trap tagged
 * every browser Sentry event "development" — production included — for months
 * before it was caught (docs/monitoring.md, 2026-08-12). A wrong label looks
 * identical to a right one, which is why this falls back to NODE_ENV rather
 * than to a hardcoded "production" that would quietly absorb staging.
 */
export function resolveEnvironment(): AppEnvironment {
  const explicit = process.env.NEXT_PUBLIC_APP_ENV;
  if (explicit && ENVIRONMENTS.includes(explicit)) return explicit as AppEnvironment;
  return process.env.NODE_ENV === "production" ? "production" : "development";
}

/**
 * The website's entire custom event surface. Deliberately small: an event
 * earns a place here only if a growth or product decision hangs on it.
 */
export interface WebEventProps {
  /** North star. A visitor clicked through to the App Store. */
  app_store_handoff: { page: string; placement: Placement; campaign_token: string };
  /** Visitor actually read the page rather than bouncing off a search result. */
  content_engaged: { page: string; page_type: PageType };
  /** Demand signal; the person is identified so the list is exportable. */
  waitlist_joined: { source: string };
}

export type WebEvent = keyof WebEventProps;

/** Returns posthog-js's capture result, which is undefined when the event
 *  could not be queued — the waitlist form depends on that signal. */
export function trackEvent<E extends WebEvent>(event: E, properties: WebEventProps[E]) {
  return posthog.capture(event, properties);
}

/**
 * Sends the full href, not the pathname. PostHog derives `$utm_*`, referrer
 * and channel type from `$current_url`, so dropping the query string here
 * would make channel attribution impossible.
 */
export function trackPageView(): void {
  posthog.capture("$pageview", { $current_url: window.location.href });
}
